/// <summary>
/// A non-2xx response decoded from the standard Databricks error envelope
/// {error_code, message}. Never carries request headers or the API token.
/// </summary>
public class DbxApiException : Exception
{
    public int StatusCode { get; }
    public string ErrorCode { get; }
    public string ApiMessage { get; }

    public DbxApiException(int statusCode, string errorCode, string apiMessage)
        : base($"Databricks API request failed ({statusCode} {errorCode}): {apiMessage}")
    {
        StatusCode = statusCode;
        ErrorCode = errorCode;
        ApiMessage = apiMessage;
    }
}

/// <summary>
/// A config update was rejected because another update is in progress (HTTP 409).
/// Must not be blindly retried; the in-flight update owns the endpoint.
/// </summary>
public sealed class ConflictException : DbxApiException
{
    public ConflictException(int statusCode, string errorCode, string apiMessage)
        : base(statusCode, errorCode, apiMessage)
    {
    }
}

/// <summary>
/// The endpoint did not reach a terminal state within the polling budget.
/// </summary>
public sealed class PollTimeoutException : Exception
{
    public string LastReady { get; }
    public string LastConfigUpdate { get; }

    public PollTimeoutException(string lastReady, string lastConfigUpdate)
        : base($"Endpoint did not settle within the polling budget; last observed state.ready={lastReady}, state.config_update={lastConfigUpdate}.")
    {
        LastReady = lastReady;
        LastConfigUpdate = lastConfigUpdate;
    }
}
