using System.Text;
using System.Text.Json;

namespace DbxServing;

/// <summary>
/// Thin typed client for the Databricks serving-endpoints REST API 2.0
/// (/api/2.0/serving-endpoints). Sends Bearer auth and Accept: application/json
/// on every request; non-2xx responses become <see cref="DbxApiException"/>
/// (409 becomes <see cref="ConflictException"/>) with the token never surfaced.
/// </summary>
public sealed class ServingClient
{
    private readonly HttpClient _http;
    private readonly string _baseUrl;
    private readonly string _token;

    public ServingClient(HttpClient http, string baseUrl, string token)
    {
        _http = http;
        _baseUrl = baseUrl.TrimEnd('/');
        _token = token;
    }

    public async Task<EndpointObservation> GetEndpointAsync(string name, CancellationToken ct) =>
        Parse(await SendAsync(HttpMethod.Get, EndpointPath(name), body: null, ct));

    public async Task<EndpointObservation> CreateEndpointAsync(EndpointSpec spec, CancellationToken ct)
    {
        var body = JsonSerializer.Serialize(new { name = spec.Name, config = ConfigBody(spec) });
        return Parse(await SendAsync(HttpMethod.Post, "/api/2.0/serving-endpoints", body, ct));
    }

    public async Task<EndpointObservation> UpdateConfigAsync(EndpointSpec spec, CancellationToken ct)
    {
        // The endpoint name travels in the path; the update body carries only the config.
        var body = JsonSerializer.Serialize(ConfigBody(spec));
        return Parse(await SendAsync(HttpMethod.Put, EndpointPath(spec.Name) + "/config", body, ct));
    }

    private static string EndpointPath(string name) =>
        "/api/2.0/serving-endpoints/" + Uri.EscapeDataString(name);

    private static object ConfigBody(EndpointSpec spec) => new
    {
        served_entities = spec.ServedEntities.Select(e => new
        {
            name = e.Name,
            entity_name = e.EntityName,
            entity_version = e.EntityVersion,
            workload_size = e.WorkloadSize,
            scale_to_zero_enabled = e.ScaleToZeroEnabled,
        }),
        traffic_config = new
        {
            routes = spec.Routes.Select(r => new
            {
                served_model_name = r.ServedModelName,
                traffic_percentage = r.TrafficPercentage,
            }),
        },
    };

    private async Task<string> SendAsync(HttpMethod method, string path, string? body, CancellationToken ct)
    {
        ct.ThrowIfCancellationRequested();
        using var request = new HttpRequestMessage(method, _baseUrl + path);
        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _token);
        request.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
        if (body is not null)
            request.Content = new StringContent(body, Encoding.UTF8, "application/json");

        using var response = await _http.SendAsync(request, ct);
        var payload = await response.Content.ReadAsStringAsync(ct);
        if (!response.IsSuccessStatusCode)
            throw Envelope((int)response.StatusCode, payload);
        return payload;
    }

    private static DbxApiException Envelope(int status, string payload)
    {
        string errorCode = "", message = payload;
        try
        {
            using var doc = JsonDocument.Parse(payload);
            if (doc.RootElement.ValueKind == JsonValueKind.Object)
            {
                if (doc.RootElement.TryGetProperty("error_code", out var code))
                    errorCode = code.GetString() ?? "";
                if (doc.RootElement.TryGetProperty("message", out var msg))
                    message = msg.GetString() ?? "";
            }
        }
        catch (JsonException)
        {
            // Not the standard envelope; keep the raw body as the message.
        }
        return status == 409
            ? new ConflictException(status, errorCode, message)
            : new DbxApiException(status, errorCode, message);
    }

    private static EndpointObservation Parse(string json)
    {
        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;

        string ready = "", configUpdate = "";
        if (root.TryGetProperty("state", out var state) && state.ValueKind == JsonValueKind.Object)
        {
            if (state.TryGetProperty("ready", out var r)) ready = r.GetString() ?? "";
            if (state.TryGetProperty("config_update", out var cu)) configUpdate = cu.GetString() ?? "";
        }

        string? endpointUrl = null;
        if (root.TryGetProperty("endpoint_url", out var url) && url.ValueKind == JsonValueKind.String)
            endpointUrl = url.GetString();

        // The active config wins; while an update deploys, the incoming entities
        // live under pending_config instead.
        JsonElement config = default;
        bool hasConfig =
            (root.TryGetProperty("config", out config) && config.ValueKind == JsonValueKind.Object) ||
            (root.TryGetProperty("pending_config", out config) && config.ValueKind == JsonValueKind.Object);

        var entities = new List<EntityStatus>();
        var routes = new List<RouteStatus>();
        if (hasConfig)
        {
            if (config.TryGetProperty("served_entities", out var served) && served.ValueKind == JsonValueKind.Array)
            {
                foreach (var entity in served.EnumerateArray())
                {
                    var name = entity.TryGetProperty("name", out var n) ? n.GetString() ?? "" : "";
                    string deployment = "", message = "";
                    if (entity.TryGetProperty("state", out var es) && es.ValueKind == JsonValueKind.Object)
                    {
                        if (es.TryGetProperty("deployment", out var d)) deployment = d.GetString() ?? "";
                        if (es.TryGetProperty("deployment_state_message", out var m)) message = m.GetString() ?? "";
                    }
                    entities.Add(new EntityStatus(name, deployment, message));
                }
            }
            if (config.TryGetProperty("traffic_config", out var traffic) && traffic.ValueKind == JsonValueKind.Object &&
                traffic.TryGetProperty("routes", out var routeArray) && routeArray.ValueKind == JsonValueKind.Array)
            {
                foreach (var route in routeArray.EnumerateArray())
                {
                    var served = route.TryGetProperty("served_model_name", out var s) ? s.GetString() ?? "" : "";
                    var pct = route.TryGetProperty("traffic_percentage", out var p) ? p.GetInt32() : 0;
                    routes.Add(new RouteStatus(served, pct));
                }
            }
        }

        return new EndpointObservation(ready, configUpdate, endpointUrl, entities, routes);
    }
}
