/// <summary>
/// Creates or updates a serving endpoint and polls it to a terminal outcome.
/// Success requires both state fields — state.ready READY and
/// state.config_update NOT_UPDATING; UPDATE_FAILED/UPDATE_CANCELED stop polling
/// immediately. All waiting goes through the injected wait delegate.
/// </summary>
public sealed class EndpointDeployer
{
    private static readonly string[] TerminalConfigUpdates = { "UPDATE_FAILED", "UPDATE_CANCELED" };

    private readonly ServingClient _client;
    private readonly Func<TimeSpan, CancellationToken, Task> _wait;
    private readonly int _maxPolls;
    private readonly TimeSpan _pollInterval;

    public EndpointDeployer(ServingClient client, Func<TimeSpan, CancellationToken, Task> wait, int maxPolls, TimeSpan pollInterval)
    {
        _client = client;
        _wait = wait;
        _maxPolls = maxPolls;
        _pollInterval = pollInterval;
    }

    public async Task<DeployResult> DeployAsync(EndpointSpec spec, CancellationToken ct)
    {
        bool created = false;
        EndpointObservation observation;
        try
        {
            await _client.GetEndpointAsync(spec.Name, ct);
            observation = await _client.UpdateConfigAsync(spec, ct);
        }
        catch (DbxApiException ex) when (ex.StatusCode == 404 && ex.ErrorCode == "RESOURCE_DOES_NOT_EXIST")
        {
            created = true;
            observation = await _client.CreateEndpointAsync(spec, ct);
        }

        int polls = 0;
        while (!IsSettled(observation))
        {
            if (polls >= _maxPolls)
                throw new PollTimeoutException(observation.Ready, observation.ConfigUpdate);
            await _wait(_pollInterval, ct);
            ct.ThrowIfCancellationRequested();
            observation = await _client.GetEndpointAsync(spec.Name, ct);
            polls++;
        }

        var entityErrors = new Dictionary<string, string>();
        foreach (var entity in observation.Entities)
        {
            if (entity.Deployment is "DEPLOYMENT_FAILED" or "DEPLOYMENT_ABORTED")
                entityErrors[entity.Name] = entity.Message;
        }

        return new DeployResult(
            created,
            observation.Ready,
            observation.ConfigUpdate,
            observation.EndpointUrl,
            observation.Entities,
            observation.Routes,
            entityErrors);
    }

    private static bool IsSettled(EndpointObservation observation) =>
        (observation.Ready == "READY" && observation.ConfigUpdate == "NOT_UPDATING") ||
        TerminalConfigUpdates.Contains(observation.ConfigUpdate);
}
"}

